@app.post("/api/subocr/config")
async def api_subocr_config(body: dict = Body(...)):
    """Save the OCR switches - config.yml, and SETTINGS in place."""
    import yaml
    allowed = {
        "subocr_auto": lambda v: bool(v),
        "subocr_every_h": lambda v: max(1, min(168, int(v))),
        "subocr_batch": lambda v: max(1, min(500, int(v))),
        "subocr_sdh": lambda v: bool(v),
        "subocr_forced": lambda v: bool(v),
        "subocr_all": lambda v: bool(v),
        "subocr_remove_image": lambda v: bool(v),
        "subocr_engine": lambda v: (str(v).lower()
                                    if str(v).lower() in ("tesseract", "paddle")
                                    else "tesseract"),
        "subocr_signs_max_cpm": lambda v: max(0.5, min(30.0, float(v))),
        "subocr_dialogue_min_cues": lambda v: max(50, min(5000, int(v))),
    }
    from . import subocr as _so_cfg
    for m in _so_cfg.RULE_META:
        allowed["subrule_" + m["key"]] = lambda v: bool(v)
    changes = {}
    for k, cast in allowed.items():
        if k in body:
            try:
                changes[k] = cast(body[k])
            except (TypeError, ValueError):
                return {"ok": False, "error": f"bad value for {k}"}
    # PER LIBRARY. {"library": "Anime Shows", "subocr_sdh": false} writes into
    # subocr_libs rather than the global default, so one shelf can differ
    # without every other shelf freezing a copy of today's default.
    lib = str(body.get("library") or "").strip()
    if lib:
        per = dict(getattr(SETTINGS, "subocr_libs", None) or {})
        cur = dict(per.get(lib) or {})
        cur.update(changes)
        per[lib] = cur
        changes = {"subocr_libs": per}
    if not changes:
        return {"ok": False, "error": "nothing to save"}
    p = _config_path()
    raw = {}
    if p.exists():
        try:
            raw = yaml.safe_load(p.read_text(encoding="utf-8-sig")) or {}
        except Exception:                                # noqa: BLE001
            raw = {}
    raw.update(changes)
    p.write_text(yaml.safe_dump(raw, sort_keys=False, allow_unicode=True),
                 encoding="utf-8")
    for k, v in changes.items():
        setattr(SETTINGS, k, v)
    joblog.log("subtitle OCR settings saved", "ok")
    from . import subocr
    return {"ok": True, **subocr.status()}


@app.post("/api/subocr/preview")
async def api_subocr_preview_change(body: dict = Body(...)):
    r"""What a proposed subtitle policy WOULD change, before it is saved.

    Same shape and the same reasoning as the language preview: look, then
    decide, then act. Saving first and counting afterwards means the planner
    has already adopted a policy nobody agreed to, and anything the queue
    picks up in between uses it.

    Scoped to ONE library, because these settings are per library - and
    because it keeps the walk to the files the change can actually reach.
    """
    from . import subocr as _so
    lib = str(body.get("library") or "").strip()
    if not lib:
        return {"ok": False, "error": "no library"}
    before = _so.sub_rules(lib)
    after = dict(before)
    for m in _so.RULE_META:
        k = "subrule_" + m["key"]
        if k in body:
            after[m["key"]] = bool(body[k])

    def _work() -> dict:
        import json as _j
        changed, checked, listed, ids = 0, 0, [], []
        with cursor() as cur:
            rows = cur.execute(
                "SELECT f.id,f.path,f.title,f.season,f.episode,f.size,"
                "       p.lang, fp.json "
                "  FROM files f JOIN file_probes fp ON fp.file_id=f.id "
                "  LEFT JOIN parent_lang p ON p.parent_id=f.arr_parent_id "
                "       AND p.arr_name=f.arr_name "
                " WHERE f.library=? AND f.state NOT IN ('deleted','duplicate')",
                (lib,)).fetchall()
        for r in rows:
            try:
                info = _j.loads(r["json"])
            except Exception:                            # noqa: BLE001
                continue
            checked += 1
            kw = dict(filename=os.path.basename(r["path"] or ""),
                      size_bytes=r["size"] or 0, orig_lang=r["lang"] or "",
                      library=lib, anime=rules.is_anime(r["path"] or ""))
            try:
                a = rules.decide(info, subrules=before, **kw)
                b = rules.decide(info, subrules=after, **kw)
            except Exception:                            # noqa: BLE001
                continue
            # Only the SUBTITLE decision - which tracks survive, which get
            # their flags cleared, and whether anything is burned in.
            same = (sorted(a.keep_subs) == sorted(b.keep_subs)
                    and sorted(a.clear_flags) == sorted(b.clear_flags)
                    and getattr(a, "burn_index", None) ==
                        getattr(b, "burn_index", None)
                    and a.encode == b.encode)
            if same:
                continue
            changed += 1
            ids.append(r["id"])
            if len(listed) < 300:
                bits = []
                if getattr(a, "burn_index", None) != getattr(b, "burn_index", None):
                    bits.append("stops burning in a track"
                                if getattr(b, "burn_index", None) is None
                                else "starts burning a track in")
                dropped = set(a.keep_subs) - set(b.keep_subs)
                added = set(b.keep_subs) - set(a.keep_subs)
                if dropped:
                    bits.append(f"drops {len(dropped)} subtitle track(s)")
                if added:
                    bits.append(f"keeps {len(added)} more subtitle track(s)")
                if sorted(a.clear_flags) != sorted(b.clear_flags):
                    bits.append("different tracks switched off")
                if a.encode != b.encode:
                    bits.append("rebuilds the video" if b.encode
                                else "no longer rebuilds the video")
                listed.append({
                    "id": r["id"],
                    "label": display_label(r["title"], r["season"], r["episode"])
                             or os.path.basename(r["path"] or ""),
                    "change": "; ".join(bits) or "a different subtitle plan",
                })
        return {"ok": True, "checked": checked, "affected": changed,
                "files": listed, "ids": ids[:20000]}
    out = await asyncio.to_thread(_work)
    # Remembered so "requeue now" queues EXACTLY what was previewed, rather
    # than re-deriving it from a policy that has since been saved - by then
    # both plans are the same and the diff would be empty.
    _SUB_LAST_IMPACT["ids"] = out.get("ids") or []
    _SUB_LAST_IMPACT["at"] = time.time()
    out.pop("ids", None)
    return out


_SUB_LAST_IMPACT: dict = {"ids": [], "at": 0.0}


@app.post("/api/subocr/requeue")
async def api_subocr_requeue():
    """Replan exactly the files the last subtitle preview reported.

    LATER IS A REAL ANSWER. Nothing here is required: the rules are already
    saved and every one of these files will be replanned the next time it is
    looked at anyway. This only says "do it now" - which matters when the
    change was the point of the exercise and you would rather not wait for
    the next sweep to reach it.
    """
    ids = list(_SUB_LAST_IMPACT.get("ids") or [])
    queued = 0
    for fid in ids:
        rows = _rows("SELECT path,title,season,episode FROM files WHERE id=?",
                     (fid,))
        if not rows:
            continue
        label = display_label(rows[0]["title"], rows[0]["season"],
                              rows[0]["episode"])
        try:
            if await jobs.enqueue(fid, rows[0]["path"], label, source="manual"):
                queued += 1
        except Exception:                                # noqa: BLE001
            continue                 # already queued, or nothing to do
    if queued:
        await jobs.start()
    joblog.log(f"subtitle rules: queued {queued} file(s) to be replanned", "ok")
    return {"queued": queued, "considered": len(ids)}


